            var i, j;
            for (i = 0; i < this.KEYS.length; i++) {
                var g = this.KEYS[i];
                a[g] = this._active(dec, period, g);
                var row = this.P[g][a[g]];
                for (j = 0; j < 7; j++) { sums[j] += row[j]; }
            }
            var cra = this._clamp(c.CRA0 + sums[4], 0.0, 100.0);
            var hh = c.K0 + sums[5];
            var x = c.X0 + sums[6];
            var xpaid = this.AU_M[a.conduct4] * x;
            var vol = 1.0 + sums[0] + c.KREV * (hh - c.K0);
            var rev = c.REV0 * vol;
            var vr = c.VAR0 * vol;
            var paid = sums[2] + xpaid;
            var profit = rev - vr - c.FIX - sums[1] - paid;
            var fraud = (a.bsa3 === 'coach') || (a.conduct4 === 'hide');
            return { a: a, vol: vol, rev: rev, vr: vr, cost: sums[1], pen: sums[2], x: x, xpaid: xpaid, paid: paid,
                     cra: cra, hh: hh, f: sums[3], profit: profit, fraud: fraud };
        }

        _components(m) {
            var c = this.C;
            var p = this._clamp((m.profit - c.P_LO) / (c.P_HI - c.P_LO), 0, 1);
            var t = this._clamp(1.0 - m.f / c.T_MAX, 0, 1);
            var r = this._clamp((m.cra - c.R_LO) / (c.R_HI - c.R_LO), 0, 1);
            var k = this._clamp((m.hh - c.K_LO) / (c.K_HI - c.K_LO), 0, 1);
            return [p, t, r, k];
        }

        _capOf(m) {
            return m.fraud ? this.C.CAPF : 100.0;
        }

        _roundScore(state, period) {
            var c = this.C;
            var m = this._state(this._flat(state, period), period);
            var comps = this._components(m);
            var w = [c.W_P, c.W_T, c.W_R, c.W_K];
            var tw = 0, num = 0;
            var i;
            for (i = 0; i < 4; i++) { tw += w[i]; num += w[i] * comps[i]; }
            var score = 100.0 * num / tw;
            score = this._clamp(score, 0, 100);
            var cap = this._capOf(m);
            score = Math.min(score, cap);
            m.cap = cap;
            return { score: this._jsround(score), m: m };
        }

        _completed(state) {
            var d = (state && state.decisions) || {};
            var n = 0;
            while (n < this.ROUNDS.length && d['round' + (n + 1)]) { n += 1; }
            return n;
        }

        _composite(state) {
            var n = this._completed(state);
            if (n === 0) { return 0; }
            var w = this.C.PERIOD_WEIGHTS;
            var num = 0, den = 0, p;
            var capLast = 100.0;
            for (p = 1; p <= n; p++) {
                var r = this._roundScore(state, p);
                num += w[p - 1] * r.score;
                den += w[p - 1];
                if (p === n) { capLast = r.m.cap; }
            }
            var total = this._clamp(this._jsround(num / den), 0, 100);
            total = Math.min(total, this._jsround(capLast));
            return total;
        }

        _verdictKey(score) {
            if (score >= this.C.THRESH_EXCELLENT) { return 'verdict_excellent'; }
            if (score >= this.C.THRESH_GOOD) { return 'verdict_good'; }
            if (score >= this.C.THRESH_DEVELOPING) { return 'verdict_developing'; }
            return 'verdict_beginner';
        }

        _jsround(x) {
            return (x >= 0) ? Math.floor(x + 0.5) : Math.ceil(x - 0.5);
        }

        _clamp(x, lo, hi) {
            if (x < lo) { return lo; }
            if (x > hi) { return hi; }
            return x;
        }

        _str(id, fallback) {
            var el = document.getElementById(id);
            return (el && el.value) ? el.value : fallback;
        }

        _t(key) {
            var sim = window.mySimulation;
            return (sim && sim.t) ? sim.t(key) : key;
        }

        _lang() {
            var sim = window.mySimulation;
            return (sim && sim.language) ? sim.language : 'en';
        }

        _fmtInt(n) {
            var v = Math.round(Math.abs(n));
            var s = String(v);
            var sep = (this._lang() === 'es') ? '.' : ',';
            var out = '';
            var i, k = 0;
            for (i = s.length - 1; i >= 0; i--) {
                out = s.charAt(i) + out;
                k += 1;
                if (k % 3 === 0 && i > 0) { out = sep + out; }
            }
            return (n < 0 ? '-' : '') + out;
        }

        _fmtK(n) {
            var neg = n < 0;
            var v = Math.round(Math.abs(n) * 10) / 10;
            var whole = Math.floor(v);
            var dec = Math.round((v - whole) * 10);
            var body = this._fmtInt(whole) + (((this._lang() === 'es') ? ',' : '.') + String(dec));
            if (this._lang() === 'es') { return (neg ? '-' : '') + body + ' mil $'; }
            return (neg ? '-$' : '$') + body + 'k';
        }

        _one(n) {
            var s = (Math.round(n * 10) / 10).toFixed(1);
            if (this._lang() === 'es') { s = s.replace('.', ','); }
            return s;
        }

        _pct0(n) {
            var r = Math.round(n * 10) / 10;
            var s = (r === Math.floor(r)) ? String(r) : this._one(r);
            return (this._lang() === 'es') ? (s + ' %') : (s + '%');
        }

        _idx(n) {
            var r = Math.round(n * 10) / 10;
            return (r === Math.floor(r)) ? String(r) : this._one(r);
        }

        _findFmt(n) {
            var s = String(n);
            if (this._lang() === 'es') { s = s.replace('.', ','); }
            return s;
        }

        _syncControlsFromDecisions(state) {
            var period = (state && state.currentPeriod) || 1;
            var d = (state && state.decisions) || {};
            var k = d['round' + period] || {};
            (this.CONTROLS[period] || []).forEach(function(g) {
                var el = document.getElementById(g + period);
                if (el && k[g + period]) { el.value = k[g + period]; }
            });
        }

        _set(id, text) {
            var el = document.getElementById(id);
            if (el) { el.textContent = text; }
        }

        _updateBriefing(state, forcedPeriod) {
            if (!state) { return; }
            var ds = state.domainState || {};
            var period = forcedPeriod || state.currentPeriod || 1;
            var done = !!ds.finished;
            var nameEl = document.getElementById('roundName');
            if (nameEl) {
                nameEl.textContent = done ? this._t('round_done')
                    : this._t((this.ROUNDS[period - 1] || this.ROUNDS[0]).nameKey);
            }
            var pH = ds.profitHistory || [];
            var tH = ds.craHistory || [];
            var fH = ds.findHistory || [];
            var kH = ds.hhHistory || [];
            var rH = ds.revHistory || [];
            var wH = ds.paidHistory || [];
            var n = pH.length;
            this._set('plDisplay', n ? (this._fmtK(pH[n - 1]) + ' · ' + this._fmtK(wH[n - 1]) + ' ' + this._t('txt_paid')) : '-');
            this._set('compDisplay', n ? (this._findFmt(fH[n - 1]) + ' ' + this._t('txt_find') + ' · ' + this._t('txt_cra') + ' ' + this._idx(tH[n - 1])) : '-');
            this._set('cliDisplay', n ? (this._idx(kH[n - 1]) + ' ' + this._t('txt_hh') + ' · ' + this._fmtK(rH[n - 1]) + ' ' + this._t('txt_rev')) : '-');
            var sc = (ds.performance && ds.performance.overallScore) || 0;
            this._set('scoreDisplay', String(sc));
            var i;
            for (i = 0; i < this.ROUNDS.length; i++) {
                var panel = document.getElementById(this.ROUNDS[i].panel);
                if (panel) { panel.style.display = (!done && (i + 1) === period) ? '' : 'none'; }
            }
            var actions = document.getElementById('actionsRow');
            if (actions) { actions.style.display = done ? 'none' : ''; }
            this._syncControlsFromDecisions(state);
        }

        getHint(state, results) {
            var p = (results && results.period) || 1;
            var d = this._flat(state, p);
            var m = this._state(d, p);
            var a = m.a;
            if (m.fraud) { return this._t('hint_fraud'); }
            if (p === 1 && a.goal1 !== 'balanced') { return this._t('hint_goal'); }
            if (p === 1 && a.lang1 !== 'bilingual') { return this._t('hint_lang'); }
            if (p === 2 && a.price2 !== 'policy') { return this._t('hint_price'); }
            if (p === 2 && a.cra2 !== 'program') { return this._t('hint_cra'); }
            if (p === 3 && a.bsa3 !== 'file') { return this._t('hint_bsa'); }
            if (p === 3 && a.ins3 !== 'structure') { return this._t('hint_ins'); }
            if (p === 4 && a.site4 !== 'keep') { return this._t('hint_site'); }
            if (p === 4 && a.conduct4 !== 'remediate') { return this._t('hint_conduct'); }
            return null;
        }

