        getPerformanceSummary(history) {
            var state = window.mySimulation.state;
            var n = this._completed(state);
            var mm = Math.max(1, n);
            var d = this._flat(state, mm);
            var m = this._state(d, mm);
            var a = m.a;
            var composite = this._composite(state);
            var insights = [];
            insights.push(this._t({ count: 'fb_go_count', balanced: 'fb_go_balanced', flat: 'fb_go_flat', push: 'fb_go_push' }[a.goal1]));
            insights.push(this._t({ none: 'fb_la_none', bilingual: 'fb_la_bilingual', adsonly: 'fb_la_adsonly', app: 'fb_la_app' }[a.lang1]));
            if (mm >= 2) {
                insights.push(this._t({ discretion: 'fb_pr_discretion', policy: 'fb_pr_policy', central: 'fb_pr_central', overlay: 'fb_pr_overlay' }[a.price2]));
                insights.push(this._t({ none: 'fb_cr_none', program: 'fb_cr_program', buy: 'fb_cr_buy', redline: 'fb_cr_redline' }[a.cra2]));
            }
            if (mm >= 3) {
                insights.push(this._t({ ignore: 'fb_bs_ignore', file: 'fb_bs_file', close: 'fb_bs_close', coach: 'fb_bs_coach' }[a.bsa3]));
                insights.push(this._t({ refer: 'fb_in_refer', structure: 'fb_in_structure', allins: 'fb_in_allins', onecd: 'fb_in_onecd' }[a.ins3]));
            }
            if (mm >= 4) {
                insights.push(this._t({ close90: 'fb_si_close90', keep: 'fb_si_keep', closenow: 'fb_si_closenow', expand: 'fb_si_expand' }[a.site4]));
                insights.push(this._t({ fire: 'fb_co_fire', remediate: 'fb_co_remediate', quiet: 'fb_co_quiet', hide: 'fb_co_hide' }[a.conduct4]));
            }
            insights.push(this._t('fb_next'));
            var vk = this._verdictKey(composite);
            return {
                composite: composite,
                overallScore: composite,
                totalScore: composite,
                score: composite,
                performance: vk.replace('verdict_', ''),
                performanceLabel: this._t(vk),
                profit: Math.round(m.profit * 10) / 10,
                cra: Math.round(m.cra * 10) / 10,
                find: m.f,
                hh: Math.round(m.hh * 10) / 10,
                rev: Math.round(m.rev * 10) / 10,
                paid: Math.round(m.paid * 10) / 10,
                periods: (history || []).length,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var s = summary || {};
            var score = (typeof s.overallScore === 'number') ? s.overallScore : 0;
