                + '<div class="ej2283-cm-kpi">' + this._t('cm_kpi_rev') + ' <strong>' + this._fmtK(s.rev || 0) + '</strong></div>'
                + '<div class="ej2283-cm-kpi">' + this._t('cm_kpi_paid') + ' <strong>' + this._fmtK(s.paid || 0) + '</strong></div>'
                + '</div>'
                + '<div class="ej2283-cm-debrief">' + this._t('cm_debrief') + '</div>'
